pub enum Msg {
    Ping,
    Hello(String),
    Heartbeat(u32),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }

    const HEARTBEAT_PREFIX: &str = "{\"v\":2,\"type\":\"heartbeat\",\"value\":";
    if let Some(value) = bytes.strip_prefix(HEARTBEAT_PREFIX).and_then(|rest| rest.strip_suffix("}")) {
        if let Ok(sequence) = value.parse() {
            return Ok(Msg::Heartbeat(sequence));
        }
    }

    const PREFIX: &str = "{\"v\":2,\"type\":\"hello\",\"value\":\"";
    if let Some(value) = bytes.strip_prefix(PREFIX).and_then(|rest| rest.strip_suffix("\"}")) {
        return Ok(Msg::Hello(value.replace("\\\"", "\"")));
    }

    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(value) => format!(
            "{{\"v\":2,\"type\":\"hello\",\"value\":\"{}\"}}",
            value.replace('\\', "\\\\").replace('\"', "\\\"")
        ),
        Msg::Heartbeat(sequence) => format!(
            "{{\"v\":2,\"type\":\"heartbeat\",\"value\":{}}}",
            sequence
        ),
    }
}

pub fn ping_roundtrip() -> Result<Msg, String> {
    decode(&encode(&Msg::Ping))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn decodes_ping_frame() {
        assert!(matches!(decode("ping"), Ok(Msg::Ping)));
    }

    #[test]
    fn roundtrips_hello_v2_frame() {
        let message = Msg::Hello("hello".into());
        assert!(matches!(decode(&encode(&message)), Ok(Msg::Hello(value)) if value == "hello"));
    }

    #[test]
    fn roundtrips_heartbeat_frame() {
        let message = Msg::Heartbeat(42);
        assert!(matches!(decode(&encode(&message)), Ok(Msg::Heartbeat(sequence)) if sequence == 42));
    }
}
